IF OBJECT_ID(N'versato.ContenidoOrigen') IS NULL CREATE TABLE versato.ContenidoOrigen(AnalisisId uniqueidentifier NOT NULL,Tipo nvarchar(40) NOT NULL,Contenido varbinary(max) NOT NULL,Compresion varchar(10) NOT NULL DEFAULT 'GZIP',PRIMARY KEY(AnalisisId,Tipo),FOREIGN KEY(AnalisisId,Tipo) REFERENCES versato.ArchivosOrigen(AnalisisId,Tipo));
IF OBJECT_ID(N'versato.FilasOrigen') IS NULL CREATE TABLE versato.FilasOrigen(Id bigint IDENTITY PRIMARY KEY,AnalisisId uniqueidentifier NOT NULL,Tipo nvarchar(40) NOT NULL,FilaExcel int NOT NULL,EsValida bit NOT NULL,Errores nvarchar(max) NOT NULL,Advertencias nvarchar(max) NOT NULL,Original nvarchar(max) NOT NULL,Normalizado nvarchar(max) NOT NULL,UNIQUE(AnalisisId,Tipo,FilaExcel),FOREIGN KEY(AnalisisId,Tipo) REFERENCES versato.ArchivosOrigen(AnalisisId,Tipo));
IF OBJECT_ID(N'versato.PackingListDatos') IS NULL CREATE TABLE versato.PackingListDatos(FilaId bigint PRIMARY KEY REFERENCES versato.FilasOrigen(Id),PRODUCTO nvarchar(254) NULL,STYLE nvarchar(100) NULL,MATERIAL_CODE nvarchar(100) NULL,COLOR_CODE nvarchar(100) NULL,SIZE_RUN nvarchar(100) NULL,MARCA nvarchar(100) NULL,DESCRIPCION nvarchar(max) NULL,DESCRIPCION_MATERIAL nvarchar(max) NULL,DESCRIPCION_COLOR nvarchar(max) NULL,SHOP nvarchar(100) NULL,BOXES decimal(28,8) NULL,PAIRS decimal(28,8) NULL,TALLE nvarchar(max) NULL,CANTIDAD nvarchar(max) NULL);
IF OBJECT_ID(N'versato.CodigosBarraDatos') IS NULL CREATE TABLE versato.CodigosBarraDatos(FilaId bigint PRIMARY KEY REFERENCES versato.FilasOrigen(Id),PRODUCTO nvarchar(254) NULL,CAJA_MASTER nvarchar(100) NULL,LINHA nvarchar(100) NULL,REFERENCIA nvarchar(100) NULL,CABEDAL nvarchar(100) NULL,COR nvarchar(100) NULL,FACTURA nvarchar(100) NULL,CODIGO_BARRA nvarchar(254) NULL,CODIGO_CAJA nvarchar(254) NULL,PARES decimal(28,8) NULL,LOJAS nvarchar(100) NULL,TALLE nvarchar(max) NULL,CANTIDAD nvarchar(max) NULL);
IF OBJECT_ID(N'versato.EansDatos') IS NULL CREATE TABLE versato.EansDatos(FilaId bigint PRIMARY KEY REFERENCES versato.FilasOrigen(Id),PRODUCTO nvarchar(254) NULL,STYLE nvarchar(100) NULL,CABEDAL nvarchar(100) NULL,COR nvarchar(100) NULL,MARCA nvarchar(100) NULL,TALLE nvarchar(100) NULL,EAN nvarchar(100) NULL,PARES decimal(28,8) NULL);
IF OBJECT_ID(N'versato.FacturasDatos') IS NULL CREATE TABLE versato.FacturasDatos(FilaId bigint PRIMARY KEY REFERENCES versato.FilasOrigen(Id),PRODUCTO nvarchar(254) NULL,STYLE nvarchar(100) NULL,MATERIAL_CODE nvarchar(100) NULL,COLOR_CODE nvarchar(100) NULL,SIZE_RUN nvarchar(100) NULL,MARCA nvarchar(100) NULL,BOXES decimal(28,8) NULL,PAIRS decimal(28,8) NULL,UNIT decimal(28,8) NULL,AMOUNT decimal(28,8) NULL);
IF OBJECT_ID(N'versato.TallesOrigen') IS NULL CREATE TABLE versato.TallesOrigen(FilaId bigint NOT NULL REFERENCES versato.FilasOrigen(Id),Posicion int NOT NULL,TALLE nvarchar(100) NULL,CANTIDAD decimal(28,8) NULL,PRIMARY KEY(FilaId,Posicion));
IF OBJECT_ID(N'versato.CrucesCantidades') IS NULL CREATE TABLE versato.CrucesCantidades(AnalisisId uniqueidentifier NOT NULL REFERENCES versato.Analisis(Id),Posicion int NOT NULL,PRODUCTO nvarchar(254) NOT NULL,STYLE nvarchar(100) NOT NULL,MATERIAL nvarchar(100) NOT NULL,COLOR nvarchar(100) NOT NULL,TALLE nvarchar(100) NOT NULL,PACKING_LIST decimal(28,8) NULL,CODIGOS_BARRA decimal(28,8) NULL,EAN decimal(28,8) NULL,Estado nvarchar(30) NOT NULL,Problemas nvarchar(max) NOT NULL,PRIMARY KEY(AnalisisId,Posicion));
IF OBJECT_ID(N'versato.CruceOrigen') IS NULL CREATE TABLE versato.CruceOrigen(AnalisisId uniqueidentifier NOT NULL,Posicion int NOT NULL,FilaId bigint NOT NULL REFERENCES versato.FilasOrigen(Id),PRIMARY KEY(AnalisisId,Posicion,FilaId),FOREIGN KEY(AnalisisId,Posicion) REFERENCES versato.CrucesCantidades(AnalisisId,Posicion));
IF OBJECT_ID(N'versato.ConjuntosDatos') IS NULL CREATE TABLE versato.ConjuntosDatos(AnalisisId uniqueidentifier PRIMARY KEY REFERENCES versato.Analisis(Id),VersionDatos int NOT NULL DEFAULT 1,Filas int NOT NULL,Creado datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
GO
CREATE OR ALTER VIEW versato.vw_PackingList AS SELECT r.AnalisisId,a.Creado FechaCarga,a.Factura FacturaAnalisis,o.Nombre Archivo,o.Hoja,r.FilaExcel,r.EsValida,r.Errores,r.Advertencias,p.* FROM versato.PackingListDatos p JOIN versato.FilasOrigen r ON r.Id=p.FilaId JOIN versato.Analisis a ON a.Id=r.AnalisisId JOIN versato.ArchivosOrigen o ON o.AnalisisId=r.AnalisisId AND o.Tipo=r.Tipo;
GO
CREATE OR ALTER VIEW versato.vw_CodigosBarra AS SELECT r.AnalisisId,a.Creado FechaCarga,a.Factura FacturaAnalisis,o.Nombre Archivo,o.Hoja,r.FilaExcel,r.EsValida,r.Errores,r.Advertencias,p.* FROM versato.CodigosBarraDatos p JOIN versato.FilasOrigen r ON r.Id=p.FilaId JOIN versato.Analisis a ON a.Id=r.AnalisisId JOIN versato.ArchivosOrigen o ON o.AnalisisId=r.AnalisisId AND o.Tipo=r.Tipo;
GO
CREATE OR ALTER VIEW versato.vw_Eans AS SELECT r.AnalisisId,a.Creado FechaCarga,a.Factura FacturaAnalisis,o.Nombre Archivo,o.Hoja,r.FilaExcel,r.EsValida,r.Errores,r.Advertencias,p.* FROM versato.EansDatos p JOIN versato.FilasOrigen r ON r.Id=p.FilaId JOIN versato.Analisis a ON a.Id=r.AnalisisId JOIN versato.ArchivosOrigen o ON o.AnalisisId=r.AnalisisId AND o.Tipo=r.Tipo;
GO
CREATE OR ALTER VIEW versato.vw_Facturas AS SELECT r.AnalisisId,a.Creado FechaCarga,a.Factura FacturaAnalisis,o.Nombre Archivo,o.Hoja,r.FilaExcel,r.EsValida,r.Errores,r.Advertencias,p.* FROM versato.FacturasDatos p JOIN versato.FilasOrigen r ON r.Id=p.FilaId JOIN versato.Analisis a ON a.Id=r.AnalisisId JOIN versato.ArchivosOrigen o ON o.AnalisisId=r.AnalisisId AND o.Tipo=r.Tipo;
GO
CREATE OR ALTER VIEW versato.vw_TallesPacking AS SELECT p.FilaId,p.AnalisisId,p.FacturaAnalisis,p.Archivo,p.Hoja,p.FilaExcel,p.EsValida,p.PRODUCTO,p.SIZE_RUN,p.MARCA,p.BOXES,t.Posicion,t.TALLE,t.CANTIDAD CantidadPorCaja,t.CANTIDAD*p.BOXES ParesTotales FROM versato.vw_PackingList p JOIN versato.TallesOrigen t ON t.FilaId=p.FilaId;
GO
CREATE OR ALTER VIEW versato.vw_TallesCodigos AS SELECT p.FilaId,p.AnalisisId,p.FacturaAnalisis,p.Archivo,p.Hoja,p.FilaExcel,p.EsValida,p.PRODUCTO,p.CODIGO_BARRA,p.CAJA_MASTER,t.Posicion,t.TALLE,t.CANTIDAD ParesTotales FROM versato.vw_CodigosBarra p JOIN versato.TallesOrigen t ON t.FilaId=p.FilaId;
GO
CREATE OR ALTER VIEW versato.vw_CruceCantidades AS SELECT a.Creado FechaCarga,a.Factura FacturaAnalisis,c.* FROM versato.CrucesCantidades c JOIN versato.Analisis a ON a.Id=c.AnalisisId;
GO
CREATE OR ALTER VIEW versato.vw_TrazabilidadCruce AS SELECT c.AnalisisId,c.Posicion,c.PRODUCTO,c.TALLE,c.Estado,r.Tipo,r.FilaExcel,o.Nombre Archivo,o.Hoja,r.EsValida FROM versato.CrucesCantidades c JOIN versato.CruceOrigen t ON t.AnalisisId=c.AnalisisId AND t.Posicion=c.Posicion JOIN versato.FilasOrigen r ON r.Id=t.FilaId JOIN versato.ArchivosOrigen o ON o.AnalisisId=r.AnalisisId AND o.Tipo=r.Tipo;
GO
CREATE OR ALTER VIEW versato.vw_UltimoAnalisisFactura AS WITH x AS(SELECT a.Id,a.Factura,a.Creado,a.Estado,ROW_NUMBER() OVER(PARTITION BY a.Factura ORDER BY a.Creado DESC,a.Id DESC) n FROM versato.Analisis a WHERE a.Factura IS NOT NULL) SELECT Id,Factura,Creado,Estado FROM x WHERE n=1;
GO
IF NOT EXISTS(SELECT 1 FROM versato.VersionEsquema WHERE Version=2) INSERT versato.VersionEsquema(Version)VALUES(2);
